class Solution {

    public int reverse(int x) {
        int res = 0;
        while (x != 0) {
            int digit = x % 10; // keeps sign of x
            x /= 10;
            // check BEFORE multiplying so we never overflow
            if (
                res > Integer.MAX_VALUE / 10 ||
                (res == Integer.MAX_VALUE / 10 && digit > 7)
