class Solution {

    public int[] findMissingRepeatingNumbers(int[] nums) {
        long n = nums.length;
        long sn = (n * (n + 1)) / 2; // expected sum
        long s2n = (n * (n + 1) * (2 * n + 1)) / 6; // expected sum of squares (needs long)
        long s = 0,
            s2 = 0;
        for (int v : nums) {
            s += v;
            s2 += (long) v * v;
        }
        long d1 = s - sn; // x - y
        long d2 = s2 - s2n; // x^2 - y^2
        long sum = d2 / d1; // x + y   (d1 != 0 because x != y)
        long x = (d1 + sum) / 2;
        long y = x - d1;
        return new int[] { (int) x, (int) y };
    }
}

