    const n = nums.length;
    // JS numbers are exact up to 2^53, enough for n up to ~10^5 (squares ~3e14)
    const sn = (n * (n + 1)) / 2;
    const s2n = (n * (n + 1) * (2 * n + 1)) / 6;
    let s = 0,
        s2 = 0;
    for (const v of nums) {
        s += v;
        s2 += v * v;
    }
    const d1 = s - sn; // x - y
    const d2 = s2 - s2n; // x^2 - y^2
    const sum = d2 / d1; // x + y
    const x = (d1 + sum) / 2;
    const y = x - d1;
    return [x, y];
}

