class Solution {

    public List<Integer> search(String text, String pattern) {
        List<Integer> res = new ArrayList<>();
        int n = text.length(),
            m = pattern.length();
        if (m == 0 || m > n) return res;
        final long B = 256,
            M = 1_000_000_007L;
        long h = 1; // B^(m-1) mod M
        for (int i = 0; i < m - 1; i++) h = (h * B) % M;
        long pHash = 0,
            win = 0;
        for (int i = 0; i < m; i++) {
            pHash = (pHash * B + pattern.charAt(i)) % M;
            win = (win * B + text.charAt(i)) % M;
        }
        for (int i = 0; i + m <= n; i++) {
            if (
                win == pHash && text.regionMatches(i, pattern, 0, m)
            ) res.add(i); // verify on hash hit
            if (i + m < n) {
                win = (win - ((text.charAt(i) * h) % M) + M) % M; // remove leftmost char
                win = (win * B + text.charAt(i + m)) % M; // shift and add new char
            }
        }
        return res;
    }
}

