    const B = 256,
        M = 1000000007; // M*B < 2^53, so no precision loss
    let h = 1; // B^(m-1) mod M
    for (let i = 0; i < m - 1; i++) h = (h * B) % M;
    let pHash = 0,
        win = 0;
    for (let i = 0; i < m; i++) {
        pHash = (pHash * B + pattern.charCodeAt(i)) % M;
        win = (win * B + text.charCodeAt(i)) % M;
    }
    for (let i = 0; i + m <= n; i++) {
        if (win === pHash && text.startsWith(pattern, i)) res.push(i); // verify on hash hit
        if (i + m < n) {
            win = (win - ((text.charCodeAt(i) * h) % M) + M) % M; // remove leftmost char
            win = (win * B + text.charCodeAt(i + m)) % M; // shift, add new char
        }
    }
    return res;
}

