class Solution {

    // Z[i] = longest common prefix of s and s.substring(i)
    private int[] zFunction(String s) {
        int n = s.length();
        int[] z = new int[n];
        int l = 0,
            r = 0; // window [l, r) matches a prefix
        for (int i = 1; i < n; i++) {
            if (i < r) z[i] = Math.min(r - i, z[i - l]); // reuse known info
            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i]))
                z[i]++;
            if (i + z[i] > r) {
                l = i;
                r = i + z[i];
            } // extend the window
        }
        return z;
    }

    public List<Integer> search(String text, String pattern) {
        List<Integer> res = new ArrayList<>();
        int m = pattern.length();
        if (m == 0) return res;
        int[] z = zFunction(pattern + "$" + text); // '$' must not occur in either string
        for (int i = m + 1; i < z.length; i++) if (z[i] == m) res.add(
            i - m - 1
        );
        return res;
    }
}

