class Solution {

    private int[] buildLps(String p) {
        int m = p.length();
        int[] lps = new int[m];
        int len = 0; // length of current matched prefix
        for (int i = 1; i < m; ) {
            if (p.charAt(i) == p.charAt(len)) {
                lps[i++] = ++len; // extend the prefix
            } else if (len > 0) {
                len = lps[len - 1]; // fall back, retry same i
            } else {
                lps[i++] = 0;
            }
        }
        return lps;
    }

    public int strStr(String haystack, String needle) {
        int n = haystack.length(),
            m = needle.length();
        if (m == 0) return 0;
        int[] lps = buildLps(needle);
        int j = 0; // matched chars of needle
        for (int i = 0; i < n; ) {
            if (haystack.charAt(i) == needle.charAt(j)) {
                i++;
                j++;
                if (j == m) return i - m; // full match ends at i-1
            } else if (j > 0) {
                j = lps[j - 1]; // reuse matched prefix, i stays
            } else {
                i++;
            }
        }
        return -1;
    }
}

