class Solution {

    private boolean isPal(String s, int lo, int hi) {
        while (lo < hi)
            if (s.charAt(lo++) != s.charAt(hi--)) return false;
        return true;
    }

    public String shortestPalindrome(String s) {
        int n = s.length();
        int k = n;
        while (k > 0 && !isPal(s, 0, k - 1)) k--; // longest palindromic prefix
        String rest = new StringBuilder(s.substring(k))
            .reverse()
            .toString();
        return rest + s;
    }
}

